import copy
cand=copy.deepcopy(grid)
boxes=[(5,6,19,23,8),(8,10,4,9,7),(8,12,15,16,5),(14,15,15,21,8),(17,18,13,16,7),(20,24,8,14,8),(22,25,16,18,5)]
for r in range(27):
 for c in range(24):
  if grid[r][c] in (3,4):
   found=next((color for r0,r1,c0,c1,color in boxes if r0<=r<=r1 and c0<=c<=c1),None)
   cand[r][c]=found if found is not None else 9
for r0,r1,c0,c1,color in boxes:
 for r in range(r0,r1+1):
  for c in range(c0,c1+1):
   cand[r][c]=color
for r,row in enumerate(cand):
 diffs=[(c,grid[r][c],v) for c,v in enumerate(row) if v!=grid[r][c]]
 if diffs: print(r,diffs)

